import{_ as h}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as p,D as r,o as s,c as _,I as o,w as m,k as i,a as k,R as n,b as u,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const y=JSON.parse('{"title":"存储、复制与可靠性","description":"分区日志、segment、复制、ISR、水位和数据丢失边界。","frontmatter":{"title":"存储、复制与可靠性","date":"2026-11-05T00:00:00.000Z","category":"Java课程","tags":["Java","Kafka","ISR"],"description":"分区日志、segment、复制、ISR、水位和数据丢失边界。"},"headers":[],"relativePath":"courses/java/16-Kafka/08-存储复制与可靠性.md","filePath":"courses/java/16-Kafka/08-存储复制与可靠性.md","lastUpdated":1793880744000}'),g={name:"courses/java/16-Kafka/08-存储复制与可靠性.md"},E=i("h1",{id:"存储、复制与可靠性",tabindex:"-1"},[k("存储、复制与可靠性 "),i("a",{class:"header-anchor",href:"#存储、复制与可靠性","aria-label":'Permalink to "存储、复制与可靠性"'},"​")],-1),B=n('<h2 id="分区日志与-segment" tabindex="-1">分区日志与 segment <a class="header-anchor" href="#分区日志与-segment" aria-label="Permalink to &quot;分区日志与 segment&quot;">​</a></h2><p>每个分区是追加日志，物理上按 segment 切分；offset 是逻辑位置。消息保留时间和大小由 Topic 配置决定，消费并不会立即删除记录。日志清理可能按时间删除，紧凑化则保留每个 key 的较新值，两者不能混为一谈。</p><p>可以把分区想成编号连续的账本：Producer 在末尾写，Consumer 自己保存读到哪里。日志不会因为某个 Consumer 读完就被它“取走”；另一个消费组仍可从自己的位置读取。segment 是账本分卷，便于索引、过期清理和文件管理，不意味着消息跨卷后顺序消失。</p><h2 id="leader、follower-与-isr" tabindex="-1">Leader、Follower 与 ISR <a class="header-anchor" href="#leader、follower-与-isr" aria-label="Permalink to &quot;Leader、Follower 与 ISR&quot;">​</a></h2><p>分区 Leader 接收读写，Follower 跟随复制。ISR 是当前满足同步条件的副本集合；<code>acks=all</code> 的实际保障依赖 ISR、<code>min.insync.replicas</code>、副本数和不可用副本时的写入策略。单节点实验不能验证副本容错。</p><p>举例：副本数 3、<code>min.insync.replicas=2</code>、Producer <code>acks=all</code>。三副本健康时可确认；一副本离开 ISR 后仍有 2 个可继续写；只剩 1 个同步副本时应拒绝新的可靠写入。若把最小 ISR 设成 1，“all” 可能只等一个副本，故不能单看 <code>acks=all</code> 就宣称多副本安全。<a href="https://kafka.apache.org/41/configuration/producer-configs/" target="_blank" rel="noreferrer">Producer ACK 配置</a>。</p>',6),A=n('<h2 id="hw、leo-与可见性" tabindex="-1">HW、LEO 与可见性 <a class="header-anchor" href="#hw、leo-与可见性" aria-label="Permalink to &quot;HW、LEO 与可见性&quot;">​</a></h2><p>LEO（Log End Offset）指日志末端下一位置，HW（High Watermark）是已满足复制可见性条件的边界。Producer 收到确认、Consumer 能读到、业务处理成功是三个不同事件。副本故障时要检查 ISR 缩减、Leader 切换和是否允许非 ISR 副本选主。</p><p>不要把 HW 理解成“所有消费者都处理完了”；它属于 Broker 复制和可见性的边界。消费组的已提交 offset 在另一层，描述应用下一次从哪里读。两组消费者即使面对同一个 HW，也可能有不同的处理进度。</p><h2 id="最小检查" tabindex="-1">最小检查 <a class="header-anchor" href="#最小检查" aria-label="Permalink to &quot;最小检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#F69D50;">bin/kafka-topics.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --describe</span><span style="--shiki-light:#005CC5;--shiki-dark:#6CB6FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;"> learning.events</span></span></code></pre></div><p>观察每个分区的 Leader、Replicas、Isr。实验时先记下副本数与 ISR，再模拟故障；不要在生产集群随意停节点。<a href="https://kafka.apache.org/documentation/#replication" target="_blank" rel="noreferrer">Kafka 设计与复制</a>。</p>',6);function C(e,F,b,I,S,P){const l=h,c=r("ClientOnly"),d=r("Mermaid");return s(),_("div",null,[E,o(c,null,{default:m(()=>{var a,t;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((t=e.$frontmatter)==null?void 0:t.showArticleMetadata)??!0)?(s(),u(l,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),B,o(d,{id:"mermaid_382ee165",graph:"flowchart%20LR%0A%20%20%20%20P%5BProducer%5D%20--%3E%20L%5BLeader%20%E6%97%A5%E5%BF%97%5D%0A%20%20%20%20L%20--%3E%20F1%5BFollower%201%5D%0A%20%20%20%20L%20--%3E%20F2%5BFollower%202%5D%0A%20%20%20%20F1%20--%3E%20I%5BISR%20%E6%BB%A1%E8%B6%B3%E7%A1%AE%E8%AE%A4%E6%9D%A1%E4%BB%B6%5D%0A%20%20%20%20F2%20--%3E%20I%0A%20%20%20%20I%20--%3E%20A%5BProducer%20%E6%94%B6%E5%88%B0%20ACK%5D%0A%20%20%20%20A%20--%3E%20C%5BConsumer%20%E5%90%8E%E7%BB%AD%E8%AF%BB%E5%8F%96%5D"}),A])}const T=p(g,[["render",C]]);export{y as __pageData,T as default};
